// handleMultiRegistryTagsFailed records a failed tag listing. Opened from the search
// (→) it says so at the footer, with the reason when there is one; opened from the
// form it stays in the journal, except for a refused token realm (DEVDESK-629).
func (m Model) handleMultiRegistryTagsFailed(msg MultiRegistryTagsLoadedMsg) (tea.Model, tea.Cmd) {
	m.registryBrowser.AddRegistryTags(msg.EntryKey, msg.RegistryURL, msg.Alias, msg.Repo, nil)
	reason := registryFailureReason(msg.Err)
	if m.registryBrowser.tagsFromSearch {
		log.Printf("ERROR [oci_resources] registry tags on %s: %s", msg.Alias, searchErrorCause(msg.Err))
		text := tagsLoadFailedText
		if reason != "" {
			text += ": " + reason
		}
		return m, m.footer.Error(text)
	}
	log.Printf("ERROR [oci_resources] registry tags %s from %s: %v", msg.Repo, oci.RedactRegistryURL(msg.RegistryURL), msg.Err)
	if reason != "" {
		return m, m.footer.Error(reason)
	}
	return m, nil
}

// handleMultiRegistryTagsMeta stores tag metadata for one registry in the browser.
func (m Model) handleMultiRegistryTagsMeta(msg MultiRegistryTagsMetaMsg) (tea.Model, tea.Cmd) {
	if m.registryBrowser == nil || msg.Gen != m.registryBrowser.gen {
		return m, nil
	}
	if msg.Err != nil {
		log.Printf("INFO [oci_resources] tag meta unavailable for %s at %s: %v", msg.Repo, oci.RedactRegistryURL(msg.RegistryURL), msg.Err)
		return m, nil
	b.searchTable.Blur()
	b.updateFocus()
	return b, nil
}

// handleImageSearchResult records one registry's answer; a stale one is ignored.
func (m Model) handleImageSearchResult(msg ImageSearchResultMsg) (tea.Model, tea.Cmd) {
	if m.registryBrowser == nil || !m.registryBrowser.AddImageResults(msg) {
		return m, nil
	}
	oc, _ := m.registryBrowser.Outcome(msg.EntryKey)
	alias := msg.EntryKey
	if e := m.registryBrowser.entryFor(msg.EntryKey); e != nil {
		alias = entryAlias(*e)
	}
	logSearchOutcome(alias, oc, msg.Err)
	if reason := registryFailureReason(msg.Err); reason != "" {
		return m, m.footer.Error("Image search on " + alias + ": " + reason)
	}
	return m, nil
}

// logSearchOutcome logs a registry's verdict: failed as an error, refused as
// info, nothing for ok or no result. The cause goes through searchErrorCause,
// so no secret or typed text reaches the log.
func logSearchOutcome(alias string, oc imagesearch.Outcome, err error) {
	switch oc.Verdict {
	case imagesearch.VerdictFailed:
		log.Printf("ERROR [oci_resources] image search on %s: %s", alias, searchErrorCause(err))
	case imagesearch.VerdictRefused:
		log.Printf("INFO [oci_resources] image search on %s: unsupported or refused: %s", alias, searchErrorCause(err))
	}
}

